function home(){return homeHero+`<div class="trust home-trust"><span>UK-based · Cambridge</span><span>Men’s & women’s scrubs</span><span>Sizes S–XL</span><span>Medical essentials, thoughtfully selected</span></div><section class="section home-collections"><div class="section-heading"><div><span class="eyebrow">EXPLORE DOCNOVA</span><h2>Two collections.<br>One considered approach.</h2></div><p>What you wear. What you rely on.<br>Find your everyday essentials here.</p></div><div class="home-category-grid"><a class="home-category" href="#/shop?fit=Women"><img loading="lazy" src="assets/5-0.webp" alt="DocNova women’s Navy Blue scrubs"><div><span class="eyebrow">01 / MEDICAL APPAREL</span><h3>Women’s scrubs <span>↗</span></h3><p>Modern fits. Colours that feel like you.</p></div></a><a class="home-category" href="#/shop?fit=Men"><img loading="lazy" src="assets/9-0.webp" alt="DocNova men’s Green scrubs"><div><span class="eyebrow">02 / MEDICAL APPAREL</span><h3>Men’s scrubs <span>↗</span></h3><p>Considered comfort for your daily rotation.</p></div></a><a class="home-category device-category" href="#/shop?category=Medical%20Devices"><img loading="lazy" src="assets/devices/devices-studio.jpg" alt="DocNova blood pressure monitor and infrared thermometer"><div><span class="eyebrow">03 / MEDICAL DEVICES</span><h3>Essential Medical Devices <span>↗</span></h3><p>Blood pressure monitors & thermometers.</p></div></a></div></section><section class="section home-scrubs"><div class="section-heading"><div><span class="eyebrow">THE SCRUB COLLECTION</span><h2>Dress for your day.</h2></div><a class="text-link" href="#/shop?collection=Scrubs">Shop all scrubs ↗</a></div><div class="grid">${['nova-top','women-pink-top','men-royal-blue-top','nova-pant'].map(id=>products.find(p=>p.id===id)).filter(Boolean).map(card).join('')}</div><div class="home-fit-note"><span>Tops £44.99 · Trousers £49.99</span><a href="#/size-guide">Find your fit ↗</a></div></section><section class="section home-devices"><div class="device-story"><span class="eyebrow">THE MEDICAL DEVICE COLLECTION</span><h2>Small essentials.<br>A place in your<br><em>everyday routine.</em></h2><p>An upper-arm blood pressure monitor and a 1-second infrared thermometer — simple, clear and made for checking in on your health at home.</p><a class="btn" href="#/shop?category=Medical%20Devices">Explore medical devices ↗</a></div><div class="grid">${products.filter(p=>p.device).map(card).join('')}</div></section><section class="home-brand"><span class="eyebrow">THE DOCNOVA APPROACH</span><h2>For the people who care.</h2><p>A professional wardrobe with a personal point of view. Practical essentials with a place in your day. Discover a more considered approach to medical apparel and everyday care.</p><a class="text-link" href="#/about">Get to know DocNova ↗</a></section>${reviews()}`}

