function newsletter(e){e.preventDefault();welcomePopup(e.target.email.value)}
function shop(){const q=new URLSearchParams(location.hash.split('?')[1]||'');return `<div class="page-head"><span class="eyebrow">THE DOCNOVA COLLECTION</span><h1>Considered essentials.</h1><p>Modern scrubs. Effortless comfort. Find the pieces that work as hard as you do.</p></div><div class="shop-layout"><aside class="filters"><h3>Refine your edit</h3>${[['category','Category',['All','Tops','Pants','Sets','Medical Devices','Jackets','Underscrubs','Accessories']],['fit','Fit',['All','Women','Men']],['size','Size',['All',...sizes]],['color','Colour',['All',...Object.keys(colors)]],['price','Price',['All','Under £40','£40–£60','Over £60']],['fabric','Fabric',['All','Stretch blend']],['collection','Collection',['All','Scrubs','Core','Studio','Medical Essentials']]].map(([id,label,values])=>`<div><label for="filter-${id}">${label}</label><select id="filter-${id}" onchange="page=1;filterProducts()">${values.map(v=>`<option ${q.get(id)===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<button class="text-link" style="margin-top:20px" onclick="document.querySelectorAll('.filters select').forEach(s=>s.selectedIndex=0);page=1;filterProducts()">Clear filters</button></aside><div><div class="shop-top"><span id="result-count"></span><select id="sort" aria-label="Sort products" onchange="page=1;filterProducts()"><option>Featured</option><option>Newest</option><option>Best-selling</option><option>Price: low to high</option><option>Price: high to low</option></select></div><div id="results" class="grid shop-grid"></div><div id="pagination" class="pagination"></div></div></div>`}
function filterProducts(){let result=products.filter(p=>['category','fit','color','fabric','collection'].every(k=>$('#filter-'+k).value==='All'||(k==='collection'&&$('#filter-'+k).value==='Scrubs'?!p.device:p[k]===$('#filter-'+k).value)));if($('#filter-size').value!=='All')result=result.filter(p=>!p.device);const price=$('#filter-price').value;if(price==='Under £40')result=result.filter(p=>p.price<40);if(price==='£40–£60')result=result.filter(p=>p.price>=40&&p.price<=60);if(price==='Over £60')result=result.filter(p=>p.price>60);const sort=$('#sort').value;if(sort.includes('low to high'))result.sort((a,b)=>a.price-b.price);if(sort.includes('high to low'))result.sort((a,b)=>b.price-a.price);if(sort==='Newest')result.reverse();if(sort==='Best-selling')result.sort((a,b)=>Number(b.badge==='BEST SELLER')-Number(a.badge==='BEST SELLER'));$('#result-count').textContent=result.length+' essentials';$('#results').innerHTML=result.length?result.slice((page-1)*9,page*9).map(card).join(''):`<div class="empty"><h2>Your next essential is on its way.</h2><p>There are no available pieces in this selection yet.</p><button class="btn" onclick="location.hash='/shop'">Explore current collection</button></div>`;$('#pagination').innerHTML=Array.from({length:Math.ceil(result.length/9)},(_,i)=>`<button aria-label="Page ${i+1}" aria-current="${page===i+1?'page':'false'}" onclick="page=${i+1};filterProducts();document.querySelector('.shop-top').scrollIntoView()">${i+1}</button>`).join('')}
function sizeControls(){return `<div class="choices">${sizes.map(s=>`<button data-size="${s}" onclick="selectSize('${s}',this)">${s}</button>`).join('')}</div><p id="size-error" class="fine" role="alert"></p>`}
function selectSize(s,el){selectedSize=s;el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el)});const err=$('#size-error');if(err)err.textContent=''}
function quickView(id){selectedProduct=products.find(p=>p.id===id);if(selectedProduct.device){deviceQuickView(selectedProduct);return}selectedSize='';const p=selectedProduct;modal(`<img src="${imageOf(p)}" style="width:150px;height:190px;float:left;margin:0 25px 20px 0" alt="${p.name}"><span class="eyebrow">${p.fit} · ${p.color}</span><h2>${p.name}</h2><p>${money(p.price)}</p><div style="clear:both">${colourOptions(p,true)}<label>Choose your size</label>${sizeControls()}<button class="btn full" onclick="addSelected()">Add to bag — ${money(p.price)}</button><p><a class="text-link" href="#/product/${id}" onclick="closeModal()">View full details ↗</a></p>${matchingPiece(p)}</div>`)}
function addSelected(buy=false){if(!$('#modal').open){const id=location.hash.split('/')[2];selectedProduct=products.find(p=>p.id===id)||selectedProduct;selectedSize=document.querySelector('#app [data-size].selected')?.dataset.size||'';}if(selectedProduct?.device)selectedSize='Standard';if(!selectedSize){const e=$('#size-error');if(e){e.textContent='Please choose a size to continue.';e.scrollIntoView({block:'center',behavior:'smooth'})}return}addToCart(selectedProduct.id,selectedSize);closeModal();if(buy)location.hash='/checkout';else openCart()}
function addToCart(id,size){if(!products.some(p=>p.id===id)||(!sizes.includes(size)&&!(size==='Standard'&&products.find(p=>p.id===id)?.device)))throw Error('Choose a valid product and size');const item=cart.find(x=>x.id===id&&x.size===size);if(item)item.qty++;else cart.push({id,size,qty:1});persist();return {id,size,quantity:cart.find(x=>x.id===id&&x.size===size).qty}}
function cartItems(edit=true){return cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-item"><img src="${imageOf(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.device?'Medical device':p.color+' / '+x.size} · ${money(p.price)}</p>${edit?`<div class="quantity"><button aria-label="Decrease quantity" onclick="changeQty(${i},-1)">−</button><span>${x.qty}</span><button aria-label="Increase quantity" onclick="changeQty(${i},1)">+</button><button style="border:0;width:auto;font-size:12px" onclick="removeItem(${i})">Remove</button></div>`:`<span>Quantity: ${x.qty}</span>`}</div></div>`}).join('')}
let appliedCoupon=localStorage.getItem('docnova-coupon')==='WELCOME10'?'WELCOME10':'';
function subtotal(){return cart.reduce((n,x)=>n+Math.round(products.find(p=>p.id===x.id).price*100)*x.qty,0)/100}
function changeQty(i,n){cart[i].qty+=n;if(cart[i].qty<=0)cart.splice(i,1);persist();if(location.hash==='#/checkout')$('#app').innerHTML=checkout();openCart()}
function removeItem(i){cart.splice(i,1);persist();if(location.hash==='#/checkout')$('#app').innerHTML=checkout();openCart()}
function openCart(){modal(`<h2>Your bag <span style="font:16px Arial">(${cart.reduce((n,x)=>n+x.qty,0)})</span></h2>${cart.length?`<p class="fine">${subtotal()>=100?'Your order qualifies for complimentary delivery.':money(100-subtotal())+' away from complimentary delivery.'}</p>${cartItems()}<div class="cart-total"><span>Subtotal</span><span>${money(subtotal())}</span></div><p class="fine">UK delivery: £4.95, complimentary over £100.</p><button class="btn full" onclick="closeModal();location.hash='/checkout'">Continue to checkout ↗</button><p class="fine">Secure checkout by Stripe · Cards, Apple Pay, Google Pay &amp; more</p><button class="text-link" onclick="closeModal();location.hash='/shop'">Continue shopping</button>`:`<div class="empty"><p>Your everyday essentials are waiting.</p><button class="btn" onclick="closeModal();location.hash='/shop'">Explore scrubs</button></div>`}`,true)}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return '<div class="content"><h1>Product not found</h1><a href="#/shop">Return to collection</a></div>';selectedProduct=p;if(p.device){selectedSize='Standard';return devicePage(p)}selectedSize='';const gallery=photos[p.group].slice(0,6);return `<div class="pdp"><div><p class="fine"><a href="#/shop">Collection</a> / ${p.category} / ${p.name}</p><img id="main-photo" class="gallery-main" src="${imageOf(p)}" alt="${p.name} in ${p.color}. Click to enlarge." tabindex="0" role="button" onclick="zoomPhoto()" onkeydown="if(event.key==='Enter')zoomPhoto()"><div class="thumbs">${gallery.map((im,i)=>`<button aria-label="View photograph ${i+1}" onclick="document.querySelector('#main-photo').src='${im}'"><img src="${im}" alt="${p.name}, view ${i+1}"></button>`).join('')}</div><p class="fine">Styled as a complete look. ${p.category==='Sets'?'Includes one top (£44.99) and one trouser (£49.99). Combined price £94.98; no set discount.':'Includes '+p.category.toLowerCase()+' only; other items shown are styling.'}</p></div><div class="product-detail"><span class="eyebrow">THE ${p.collection.toUpperCase()} COLLECTION · ${p.fit.toUpperCase()}</span><h1>${p.name}</h1><p class="price">${money(p.price)} ${p.old?`<del>${money(p.old)}</del>`:''}</p><a class="fine text-link" href="#/reviews">★★★★★ Read our Google reviews</a><p style="margin-top:22px">A refined essential for your daily rotation. A clean silhouette, comfortable stretch and thoughtful details — so you can focus on what matters.</p>${colourOptions(p)}<div style="display:flex;justify-content:space-between"><label>Size</label><a class="text-link" href="#/size-guide">Size guide ↗</a></div>${sizeControls()}<p class="fine">A modern regular fit. Between sizes? Choose the larger size for a more relaxed feel.</p><div class="mobile-add"><button class="btn" onclick="addSelected()">Add to bag — ${money(p.price)}</button><button class="btn outline" onclick="addSelected(true)">Buy now</button></div><p class="fine">✓ Easy-care design &nbsp; ✓ Stretch comfort &nbsp; ✓ Professional fit</p>${matchingPiece(p)}${[['The details','A modern neckline, practical storage and an easy silhouette. Designed to feel comfortable through a busy day.'],['Fabric & care','Soft, lightweight stretch fabric that moves with you through a long shift. Machine wash cool with similar colours and follow the care label supplied with your garment.'],['Delivery & returns','Standard UK delivery is £4.95, or free on orders of £100 or more. Orders are usually dispatched within 1–2 working days and arrive in 3–5 working days. You’ll get an order number straight away and a tracking number once your order is on its way. Unworn, unwashed scrubs with their tags attached can be returned within 30 days of delivery for a full refund of the item price. Medical devices can be returned within 30 days if unopened and in their original sealed packaging. Return postage is paid by the customer unless the item is faulty or we sent the wrong item. Email info@docnova.co.uk with your order number to start a return. This does not affect your statutory rights.']].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}</div></div><section class="section"><div class="section-heading"><h2>Complete your rotation.</h2><a class="text-link" href="#/shop">Shop all ↗</a></div><div class="grid">${products.filter(x=>x.id!==id&&x.fit===p.fit).slice(0,4).map(card).join('')}</div></section><section class="section" style="padding-top:0"><h2>You may also like.</h2><div class="grid">${products.filter(x=>x.id!==id&&x.fit!==p.fit).slice(0,4).map(card).join('')}</div></section>${reviews()}`}
function zoomPhoto(){const src=$('#main-photo').src;modal(`<img src="${src}" style="max-height:76vh;object-fit:contain" alt="Enlarged product photograph">`)}
function openSearch(){modal(`<h2>Find your everyday.</h2><input class="search-input" aria-label="Search products" placeholder="Try navy, sets, or women…" oninput="searchResults(this.value)" autofocus><div id="search-results"></div>`);searchResults('')}
function searchResults(q){const list=products.filter(p=>(p.name+' '+p.color+' '+p.category+' '+p.fit).toLowerCase().includes(q.toLowerCase())).slice(0,6);$('#search-results').innerHTML=list.length?list.map(p=>`<a class="search-result" href="#/product/${p.id}" onclick="closeModal()"><img src="${imageOf(p)}" alt=""><div>${p.name}<br><span class="fine">${p.color} · ${money(p.price)}</span></div></a>`).join(''):'<p>No pieces found. Try a colour or category.</p>'}
function menu(){modal(`<h2>Explore DocNova</h2><div class="mega"><a href="#/" onclick="closeModal()">Home</a>${['Tops','Pants','Sets','Medical Devices','Jackets','Underscrubs','Accessories'].map(c=>`<a href="#/shop?category=${c}" onclick="closeModal()">${c} ↗</a>`).join('')}<a href="#/about" onclick="closeModal()">Our story</a><a href="#/size-guide" onclick="closeModal()">Size guide</a></div>`)}
function account(){modal(`<h2>Your DocNova space.</h2><p>Keep your favourites close and pick up where you left off.</p><p class="fine">Your bag and wishlist are saved on this device.</p><button class="btn" onclick="closeModal();location.hash='/wishlist'">View your wishlist</button>`)}
const faqs=[['How do I choose my size?','All men’s and women’s scrubs come in Small (S), Medium (M), Large (L) and XL, in a modern regular fit. If you are between sizes, choose the larger size for a more relaxed feel. Email info@docnova.co.uk or call 07446 961888 and we’ll help you choose.'],['What is included in a scrub set?','Each set includes one matching top and one pair of trousers. Individual tops and pants are sold separately, even when photographed as a complete outfit.'],['How should I care for my scrubs?','Machine wash cool with similar colours and follow the care label supplied with your garment.'],['Where do you deliver?','We deliver anywhere in the United Kingdom. Standard UK delivery is £4.95, or free on orders of £100 or more. Orders are usually dispatched within 1–2 working days and arrive in 3–5 working days. You’ll get an order number straight away and a tracking number once your order is on its way.'],['Can I return an item?','Unworn, unwashed scrubs with their tags attached can be returned within 30 days of delivery for a full refund of the item price. Medical devices can be returned within 30 days if unopened and in their original sealed packaging. Return postage is paid by the customer unless the item is faulty or we sent the wrong item. Email info@docnova.co.uk with your order number to start a return. This does not affect your statutory rights.'],['How can I pay?','Checkout takes you to a secure Stripe payment page. Depending on your device you can pay by debit or credit card, Apple Pay, Google Pay, Link and other options shown on the checkout page. DocNova never sees or stores your card details.'],['How do I track my order?','After payment you receive an order number such as DN-260926-7K4QP. Enter it with the email you used at checkout on the <a class="text-link" href="#/track-order">Track your order</a> page to see its status and, once dispatched, the tracking number.']];
function sizeGuide(){return `<div class="content"><span class="eyebrow">SIZE & FIT</span><h1>Find your everyday fit.</h1><p>All men’s and women’s scrubs are available in Small, Medium, Large and XL.</p><div class="table-wrap"><table><caption>Available sizes for men and women</caption><thead><tr><th>Size</th><th>Label</th><th>Range</th></tr></thead><tbody>${[['S','Small'],['M','Medium'],['L','Large'],['XL','Extra Large']].map(([size,label])=>`<tr><th>${size}</th><td>${label}</td><td>Men & women</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:40px">Taking your measurements</h3><p>Measure around the fullest part of your chest and hips, and your natural waist. Keep the tape level without pulling it tight.</p><p>Between sizes? Choose the larger size for a more relaxed feel. If you are unsure which size to choose, contact us for sizing advice.</p><a class="text-link" href="#/shop">Explore the collection ↗</a></div>`}
function checkout(){if(!cart.length)return `<div class="content"><h1>Your bag is waiting.</h1><p>Add an essential to begin your checkout.</p><a class="btn" href="#/shop">Shop scrubs</a></div>`;return `<div class="checkout"><div><span class="eyebrow">BAG / SECURE PAYMENT / CONFIRMATION</span><h1>A better shift awaits.</h1><h3>Delivery</h3><p>Standard UK delivery · ${subtotal()>=100?'Complimentary':'£4.95'}<br><span class="fine">Usually 3–5 working days. You’ll add your delivery address on the secure payment page.</span></p><h3 style="margin-top:30px">Ways to pay</h3><div id="pay-methods" class="pay-methods">${payMethodsMarkup()}</div><p class="fine">The options that suit your device appear on the next page, for example Apple Pay on iPhone and Safari, or Google Pay on Android and Chrome.</p><div id="checkout-error" class="notice" role="alert" hidden></div><button id="pay-button" class="btn full" style="margin-top:25px" onclick="startCheckout()">Continue to secure payment ↗</button><p class="fine secure-note">Payments are processed securely by Stripe. DocNova never sees or stores your card details. You’ll receive an order number to track your order.</p></div><aside class="order-summary"><h2 style="font-size:30px">Your essentials</h2>${cartItems(false)}<div class="cart-total"><span>Subtotal</span><span>${money(subtotal())}</span></div><p>Delivery <span style="float:right">${subtotal()>=100?'Free':money(4.95)}</span></p><div id="checkout-offer">${couponMarkup()}</div><div class="cart-total"><strong>Total</strong><strong id="order-total">${money(orderTotal())}</strong></div><p class="fine">Prices shown in GBP.</p><button class="text-link" onclick="openCart()">Edit bag</button></aside></div>`}
function route(){if($('#modal').open)closeModal();const route=(location.hash.slice(1)||'/').split('?')[0];let html='';if(route==='/')html=home();else if(route==='/shop')html=shop();else if(route.startsWith('/product/'))html=productPage(route.split('/')[2]);else if(route==='/wishlist')html=`<div class="page-head"><span class="eyebrow">YOUR PERSONAL EDIT</span><h1>Saved for your next shift.</h1></div><section class="section" style="padding-top:0"><div class="grid">${wishlist.length?products.filter(p=>wishlist.includes(p.id)).map(card).join(''):'<div class="empty"><p>Your wishlist is ready for your favourites.</p><a class="btn" href="#/shop">Explore the collection</a></div>'}</div></section>`;else if(route==='/about')html=`<section class="story"><img src="assets/9-0.webp" alt="Healthcare professional in green scrubs"><div class="story-copy"><span class="eyebrow">THE DOCNOVA POINT OF VIEW</span><h1>Care is personal.<br><em>Your uniform should be, too.</em></h1><p>What you wear to work should support the way you move, the way you feel, and the professional you are.</p><p>DocNova brings a considered approach to medical apparel: confident silhouettes, thoughtful functionality and comfort at the centre of every design.</p><a class="btn" href="#/shop">Meet your new essentials</a></div></section><section class="content"><h2>Quiet confidence. Every day.</h2><p>We believe a uniform can be both practical and personal. That feeling put together matters. And that the smallest details can make your everyday feel better.</p><p>Our design direction is simple: create fewer distractions, more freedom to move, and a clean, professional presence.</p><p>Alongside our scrubs we supply a small range of essential medical devices — an upper-arm blood pressure monitor and an infrared thermometer — chosen to be simple, clear and reliable for use at home.</p><p>DocNova is an independent UK company based in Cambridge. If you have a question, you can reach us directly on <a class="text-link" href="mailto:info@docnova.co.uk">info@docnova.co.uk</a> or <a class="text-link" href="tel:+447446961888">07446 961888</a>.</p></section>`;else if(route==='/size-guide')html=sizeGuide();else if(route==='/reviews')html=reviews();else if(route==='/faq')html=`<div class="content"><span class="eyebrow">HERE TO HELP</span><h1>A few good answers.</h1>${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;else if(route==='/checkout')html=checkout();else if(route==='/order-confirmed'||route==='/confirmation')html=orderConfirmedPage();else if(route==='/track-order')html=trackOrderPage();else{const texts={"shipping": ["Delivery & returns", "<h3>Delivery</h3><p>We deliver anywhere in the United Kingdom. Standard delivery is £4.95, and free on orders of £100 or more.</p><p>Orders are usually dispatched within 1–2 working days and arrive in 3–5 working days. You’ll receive an order number as soon as you pay, and a tracking number by email once your order is on its way. You can check progress any time on the <a class=\"text-link\" href=\"#/track-order\">Track your order</a> page.</p><h3>Returns</h3><p>Changed your mind? Unworn, unwashed scrubs with their tags attached can be returned within 30 days of delivery for a full refund of the item price.</p><p>For hygiene reasons, blood pressure monitors and thermometers can be returned only if unopened and in their original sealed packaging.</p><p>To start a return, email <a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a> with your order number and the items you’re sending back. Return postage is paid by you unless the item is faulty or we sent the wrong item. We refund to your original payment method within 14 days of receiving your return.</p><h3>Faulty or wrong items</h3><p>If something arrives damaged, faulty or isn’t what you ordered, contact us within 30 days and we’ll put it right with a replacement or full refund, including postage.</p><p>These terms don’t affect your statutory rights under the Consumer Rights Act 2015 and the Consumer Contracts Regulations 2013.</p>"], "privacy": ["Privacy policy", "<p>DocNova Ltd (company no. 16502835, based in Cambridge, UK) is responsible for the personal data we collect through this website. Contact us at <a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a> about anything in this notice.</p><h3>What we collect and why</h3><p><strong>Orders:</strong> your name, email address, phone number, delivery address and what you bought — to take payment, deliver your order, send order and tracking emails and handle returns (needed to perform our contract with you).</p><p><strong>Payments:</strong> handled by Stripe. We never see or store your full card details.</p><p><strong>Newsletter:</strong> if you sign up, your email address and the time you agreed — to send collection news and offers (with your consent). Every email has an unsubscribe link.</p><p><strong>Your bag and wishlist:</strong> saved in your own browser, not on our servers.</p><h3>Who we share it with</h3><p>Only the services that help us run the shop: Stripe (payments), our email provider (order and newsletter emails), our website host and the delivery carrier. We never sell your data.</p><h3>How long we keep it</h3><p>Order records are kept for six years for tax and accounting. Newsletter details are kept until you unsubscribe.</p><h3>Your rights</h3><p>You can ask for a copy of your data, or ask us to correct or delete it, by emailing <a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a>. If you are unhappy with how we handle your data you can complain to the Information Commissioner’s Office (ico.org.uk).</p><p>This website doesn’t use advertising or analytics cookies.</p>"], "terms": ["Terms of sale", "<p>These terms apply to orders placed on docnova.co.uk with DocNova Ltd, registered in England & Wales (company no. 16502835) and based in Cambridge, UK.</p><h3>Orders and prices</h3><p>Prices are shown in pounds sterling. Your order is accepted when payment is confirmed and you receive your order number. If we can’t fulfil an order — for example if an item is out of stock — we’ll tell you and refund you in full.</p><h3>Payment</h3><p>Payments are processed securely by Stripe. The payment methods available depend on your device and are shown at checkout.</p><h3>Delivery, cancellations and returns</h3><p>We deliver within the UK. You have the right to cancel within 14 days of receiving your order, and our 30-day returns policy gives you longer — see <a class=\"text-link\" href=\"#/shipping\">Delivery & returns</a>.</p><h3>Medical devices</h3><p>Our blood pressure monitors and thermometers are for home use. Always read the user manual supplied with your device. Readings are not a diagnosis — speak to your GP or pharmacist about your results, and call 999 or 111 in an emergency.</p><h3>Law</h3><p>These terms are governed by the laws of England and Wales. Nothing in them affects your statutory rights.</p>"], "contact": ["Let’s talk.", "<p>Questions about sizing, an order or our medical devices? We’re happy to help.</p><div class=\"contact-cards\"><div><span class=\"eyebrow\">EMAIL</span><p><a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a></p></div><div><span class=\"eyebrow\">PHONE</span><p><a class=\"text-link\" href=\"tel:+447446961888\">07446 961888</a></p></div><div><span class=\"eyebrow\">HOURS</span><p>Every day, 8am – 8pm</p></div><div><span class=\"eyebrow\">BASED IN</span><p>Cambridge, UK</p></div></div><p>For an existing order, please include your order number (it starts with DN-). You can also <a class=\"text-link\" href=\"#/track-order\">track your order</a> online.</p>"]};const t=texts[route.slice(1)];html=t?`<div class="content policy"><h1>${t[0]}</h1>${t[1]}${route==='/privacy'?'<button class="btn" onclick="clearData()">Clear my saved bag and wishlist</button>':'<p style="margin-top:28px"><a class="text-link" href="#/faq">Read our FAQs ↗</a></p>'}</div>`:'<div class="content"><h1>Let’s get you back.</h1><a class="btn" href="#/">Return home</a></div>'}$('#app').innerHTML=html;if(route==='/shop')filterProducts();if(route==='/order-confirmed'||route==='/confirmation')loadConfirmedOrder();loadGoogleReviews();if(route==='/track-order'&&hashParam('order')&&hashParam('email'))trackOrder();document.title='DocNova — '+(route==='/'?'Premium Scrubs & Medical Essentials':route.startsWith('/product/')?selectedProduct?.name||'Collection':route.slice(1).replaceAll('-',' '));window.scrollTo(0,0);persist()}
function clearData(){cart=[];wishlist=[];appliedCoupon='';['docnova-cart','docnova-wishlist','docnova-newsletter','docnova-coupon','docnova-welcome-subscribed'].forEach(k=>localStorage.removeItem(k));sessionStorage.removeItem('docnova-order');sessionStorage.removeItem('docnova-welcome-seen');persist();toast('Saved bag and wishlist cleared')}
window.addEventListener('hashchange',route);route();
// Optional browser agent tools share the same catalogue and cart actions as the UI.
if(document.modelContext?.registerTool){for(const tool of [{name:'search_docnova_products',description:'Read matching products in the local DocNova catalogue.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({query})=>{if(typeof query!=='string')throw Error('query must be a string');return products.filter(p=>(p.name+' '+p.color+' '+p.category).toLowerCase().includes(query.toLowerCase())).map(({id,name,price,color})=>({id,name,price,color}))}},{name:'add_docnova_item_to_bag',description:'Add one product and size to the local shopping bag. Does not place an order.',inputSchema:{type:'object',properties:{id:{type:'string'},size:{type:'string',enum:[...sizes,'Standard']}},required:['id','size'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({id,size})=>{const result=addToCart(id,size);openCart();return result}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}



if(removedUnavailableSizes)toast('Your bag was updated: only S, M, L and XL are available.');

function deviceQuickView(p){selectedSize='Standard';modal(`<img src="${imageOf(p)}" style="width:150px;height:190px;object-fit:contain;float:left;margin:0 25px 20px 0" alt="${p.name}"><span class="eyebrow">MEDICAL ESSENTIALS</span><h2>${p.name}</h2><p>${money(p.price)}</p><div style="clear:both"><button class="btn full" onclick="addSelected()">Add to bag — ${money(p.price)}</button><p><a class="text-link" href="#/product/${p.id}" onclick="closeModal()">View full details ↗</a></p></div>`)}
function devicePage(p){return `<div class="pdp"><div><p class="fine"><a href="#/shop?category=Medical%20Devices">Medical devices</a> / ${p.name}</p><img id="main-photo" class="gallery-main device-photo" src="${imageOf(p)}" alt="${p.name}" tabindex="0" role="button" onclick="zoomPhoto()" onkeydown="if(event.key==='Enter')zoomPhoto()"><div class="thumbs">${photos[p.group].map((im,i)=>`<button aria-label="View photograph ${i+1}" onclick="document.querySelector('#main-photo').src='${im}'"><img src="${im}" alt="${p.name}, view ${i+1}"></button>`).join('')}</div></div><div class="product-detail"><span class="eyebrow">MEDICAL ESSENTIALS</span><h1>${p.name}</h1><p class="price">${money(p.price)}</p>${(()=>{const d=deviceInfo[p.id];return d?`<p style="margin-top:18px">${d.intro}</p><ul class="device-points">${d.bullets.map(b=>`<li>${b}</li>`).join('')}</ul>`:''})()}<div class="mobile-add"><button class="btn" onclick="addSelected()">Add to bag — ${money(p.price)}</button><button class="btn outline" onclick="addSelected(true)">Buy now</button></div>${(()=>{const d=deviceInfo[p.id];return d?`<details open><summary>Specifications</summary><table class="spec-table">${d.specs.map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</table></details><details><summary>What’s in the box</summary><ul class="device-points">${d.box.map(b=>`<li>${b}</li>`).join('')}</ul></details><details><summary>Using your device safely</summary><p>For home use. Read the user manual before first use. Readings are for information and don’t replace advice from a healthcare professional — speak to your GP or pharmacist about your results, and call 999 or 111 in an emergency.</p></details>`:''})()}<details><summary>Delivery & returns</summary><p>Standard UK delivery is £4.95, or free on orders of £100 or more. Orders are usually dispatched within 1–2 working days and arrive in 3–5 working days. You’ll get an order number straight away and a tracking number once your order is on its way.</p><p>Devices can be returned within 30 days if unopened and in their original sealed packaging. <a class="text-link" href="#/shipping">Delivery & returns ↗</a></p></details></div></div><section class="section"><h2>More medical essentials.</h2><div class="grid">${products.filter(x=>x.device&&x.id!==p.id).map(card).join('')}</div></section>`}

function colourOptions(p,quick=false){const variants=products.filter(x=>!x.device&&x.category===p.category&&x.fit===p.fit);return `<div class="colour-picker"><p>Colour — <strong>${p.color}</strong></p><div class="colour-options" aria-label="Available colours">${variants.map(v=>quick?`<button class="colour-option ${v.id===p.id?'active':''}" aria-pressed="${v.id===p.id}" onclick="quickView('${v.id}')"><span style="background:${colors[v.color]}"></span>${v.color}</button>`:`<a class="colour-option ${v.id===p.id?'active':''}" aria-current="${v.id===p.id?'true':'false'}" href="#/product/${v.id}"><span style="background:${colors[v.color]}"></span>${v.color}</a>`).join('')}</div></div>`}
function matchingPiece(p){if(!['Tops','Pants'].includes(p.category))return '';const match=products.find(x=>x.fit===p.fit&&x.color===p.color&&x.category===(p.category==='Tops'?'Pants':'Tops'));if(!match)return '';return `<aside class="matching-piece" aria-label="Complete the set"><span class="eyebrow">COMPLETE THE SET</span><p>Pair it with the matching ${p.category==='Tops'?'trousers':'top'} in ${p.color}.</p><div class="matching-product"><a href="#/product/${match.id}" onclick="closeModal()"><img src="${imageOf(match)}" alt="${match.name}"></a><div><a class="matching-title" href="#/product/${match.id}" onclick="closeModal()">${match.name}</a><p>${match.fit} · ${money(match.price)}</p><button class="text-link" onclick="quickView('${match.id}')">Choose size & add ↗</button></div></div><small>Top + trousers: ${money(p.price+match.price)}. Choose each size separately.</small></aside>`}

function discountAmount(){return appliedCoupon==='WELCOME10'?Math.round(subtotal()*100*0.1)/100:0}
function orderTotal(){return Math.round((subtotal()-discountAmount()+(subtotal()>=100?0:4.95))*100)/100}
function couponMarkup(){return `<form class="coupon-form" onsubmit="applyCoupon(event)"><label for="discount-code">Discount code</label><div><input id="discount-code" name="coupon" autocomplete="off" placeholder="Enter code" value="${appliedCoupon}"><button type="submit">Apply</button></div></form><p id="coupon-message" role="status" class="fine">${appliedCoupon?'WELCOME10 applied — 10% off your items.':''}</p>${appliedCoupon?`<p class="discount-line">WELCOME10 · 10% off <strong>−${money(discountAmount())}</strong> <button type="button" onclick="removeCoupon()" aria-label="Remove discount">×</button></p>`:''}`}
function applyCoupon(e){e.preventDefault();const code=e.target.coupon.value.trim().toUpperCase();if(code!=='WELCOME10'){$('#coupon-message').textContent='That code is not recognised. Please check and try again.';return}appliedCoupon='WELCOME10';localStorage.setItem('docnova-coupon',appliedCoupon);refreshCoupon()}
function removeCoupon(){appliedCoupon='';localStorage.removeItem('docnova-coupon');refreshCoupon()}
function refreshCoupon(){if($('#checkout-offer')){$('#checkout-offer').innerHTML=couponMarkup();$('#order-total').textContent=money(orderTotal())}}
function welcomePopup(prefill=''){sessionStorage.setItem('docnova-welcome-seen','1');modal(`<div class="welcome-layout"><img class="welcome-image" src="assets/2-1.webp" alt="DocNova Pink premium scrubs"><div class="welcome-copy"><span class="eyebrow">WELCOME TO DOCNOVA</span><h2>Your essentials.<br>A little welcome gift.</h2><p class="welcome-discount">Enjoy <strong>10% off</strong></p><p>Subscribe to DocNova emails for new arrivals, updates and your welcome offer.</p><div class="welcome-code">Your code <strong>WELCOME10</strong></div><form id="welcome-form" onsubmit="subscribeWelcome(event)"><label for="welcome-email">Email address</label><input id="welcome-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"><label class="welcome-consent"><input type="checkbox" name="consent" required> <span>I’d like to receive DocNova emails and my welcome discount. I can unsubscribe at any time.</span></label><button class="btn full" type="submit">Subscribe & email my code</button><p id="welcome-status" role="status" aria-live="polite"></p></form><p class="fine">10% off products, excluding delivery. One code per order. <a href="#/privacy" onclick="closeModal()">Privacy notice</a></p><button class="text-link" onclick="closeModal()">Continue browsing</button></div></div>`);$('#modal').classList.add('welcome-dialog');$('#welcome-email').value=prefill}
async function subscribeWelcome(e){e.preventDefault();const form=e.target;const status=$('#welcome-status');const button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent='Saving your subscription…';try{const response=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.email.value.trim(),consent:form.consent.checked})});const result=await response.json();if(!response.ok)throw new Error(result.message||'We couldn’t complete your signup. Please try again.');localStorage.setItem('docnova-welcome-subscribed','1');status.textContent=result.status==='sent'?'You’re subscribed. Your welcome email is on its way with WELCOME10.':'Thanks — you’re on the list. Use code WELCOME10 at checkout for 10% off.';button.textContent=result.status==='sent'?'Subscribed':'Subscribed';form.email.disabled=true;form.consent.disabled=true}catch(error){status.textContent='Sorry, we couldn’t sign you up just now. Please try again later — you can still use WELCOME10 at checkout.';button.disabled=false}}
setTimeout(()=>{if(!sessionStorage.getItem('docnova-welcome-seen')&&!localStorage.getItem('docnova-welcome-subscribed')&&!$('#modal').open&&!location.hash.startsWith('#/checkout'))welcomePopup()},1400);

// ---- Stripe checkout, order confirmation and order tracking
var payInfo=null; // var: the footer renders before this line runs
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pence(n){return money((n||0)/100)}
function hashParam(name){return new URLSearchParams(location.hash.split('?')[1]||'').get(name)||''}
function payMethodsMarkup(){const list=payInfo?.methods||[{label:'Visa · Mastercard · Amex'},{label:'Apple Pay'},{label:'Google Pay'},{label:'Link'}];return list.map(m=>`<span class="pay-chip">${esc(m.label)}</span>`).join('')}
fetch('/api/payment-methods').then(r=>r.ok?r.json():null).then(d=>{if(!d)return;payInfo=d;document.querySelectorAll('#pay-methods,#footer-pay').forEach(el=>el.innerHTML=payMethodsMarkup())}).catch(()=>{});
async function startCheckout(){const btn=$('#pay-button'),err=$('#checkout-error');err.hidden=true;btn.disabled=true;btn.textContent='Opening secure payment…';
 try{const res=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart.map(x=>({id:x.id,size:x.size,qty:x.qty})),coupon:appliedCoupon})});
  const data=await res.json().catch(()=>({}));if(res.ok&&data.url){sessionStorage.setItem('docnova-pending-order',data.order_number);location.href=data.url;return}
  throw Error(data.message||'We could not start secure checkout. Please try again.')}
 catch(e){err.textContent=e.message.includes('fetch')?'Checkout is unavailable right now. Please check your connection and try again.':e.message;err.hidden=false;btn.disabled=false;btn.textContent='Continue to secure payment ↗'}}
var ORDER_STEPS=[['placed','Order placed'],['paid','Payment confirmed'],['dispatched','Dispatched'],['delivered','Delivered']];
function orderSteps(o){const reached={placed:1,paid:['paid','dispatched','delivered'].includes(o.status),dispatched:['dispatched','delivered'].includes(o.status),delivered:o.status==='delivered'};
 const when={placed:o.created_at,paid:o.paid_at,dispatched:o.dispatched_at,delivered:o.delivered_at};
 return `<ol class="order-steps">${ORDER_STEPS.map(([k,l])=>`<li class="${reached[k]?'done':''}"><span></span><b>${l}</b>${reached[k]&&when[k]?`<small>${new Date(when[k]*1000).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}</small>`:''}</li>`).join('')}</ol>`}
function orderCard(o){const alert={payment_failed:'Your payment did not go through, so this order will not be sent. Please place a new order.',expired:'This checkout was not completed and no payment was taken.',processing:'Your payment is being confirmed by your bank. This can take up to a few working days; we’ll dispatch as soon as it clears.',cancelled:'This order has been cancelled.',refunded:'This order has been refunded.',partially_refunded:'Part of this order has been refunded.'}[o.status];
 return `<div class="order-card"><div class="order-head"><div><span class="eyebrow">ORDER NUMBER</span><strong class="order-number">${esc(o.order_number)}</strong></div><span class="order-status status-${esc(o.status)}">${esc(o.status_label)}</span></div>
 ${alert?`<div class="notice">${alert}</div>`:orderSteps(o)}
 ${o.tracking_number?`<div class="tracking-box"><span class="eyebrow">TRACKING</span><p><b>${esc(o.carrier||'Carrier')}</b> · ${esc(o.tracking_number)}</p>${o.tracking_url?`<a class="btn" href="${esc(o.tracking_url)}" target="_blank" rel="noopener">Track with ${esc(o.carrier||'carrier')} ↗</a>`:''}</div>`:''}
 <div class="order-lines">${o.items.map(i=>`<div><span>${i.qty} × ${esc(i.name)}${i.size==='Standard'?'':' · '+esc(i.size)}</span><span>${pence(i.unit_pence*i.qty)}</span></div>`).join('')}
 ${o.discount?`<div><span>Discount${o.coupon?' ('+esc(o.coupon)+')':''}</span><span>−${pence(o.discount)}</span></div>`:''}<div><span>Delivery</span><span>${o.shipping?pence(o.shipping):'Free'}</span></div><div class="cart-total"><strong>Total</strong><strong>${pence(o.total)}</strong></div></div>
 ${o.ship_to?`<p class="fine">Delivering to ${esc(o.name||'')}${o.name?', ':''}${esc(o.ship_to)}</p>`:''}</div>`}
function orderConfirmedPage(){return `<div class="content order-page" id="order-confirmed"><span class="eyebrow">YOUR DOCNOVA ORDER</span><h1>Confirming your order…</h1><p>Just a moment while we confirm your payment with Stripe.</p></div>`}
async function loadConfirmedOrder(attempt=0){const sid=hashParam('session_id'),box=$('#order-confirmed');if(!box)return;
 if(!sid){box.innerHTML=`<span class="eyebrow">YOUR DOCNOVA ORDER</span><h1>Looking for an order?</h1><p>Use your order number and email to see its status.</p><a class="btn" href="#/track-order">Track your order</a>`;return}
 try{const res=await fetch('/api/order?session_id='+encodeURIComponent(sid));const o=await res.json();if(!res.ok)throw Error(o.message);
  if(['paid','processing','dispatched','delivered'].includes(o.status)){cart=[];appliedCoupon='';try{localStorage.removeItem('docnova-coupon');sessionStorage.removeItem('docnova-pending-order')}catch(e){};persist()}
  if(o.status==='awaiting_payment'&&attempt<6){setTimeout(()=>loadConfirmedOrder(attempt+1),2000);return}
  const ok=['paid','dispatched','delivered'].includes(o.status);
  box.innerHTML=`<span class="eyebrow">${ok?'THANK YOU':'YOUR DOCNOVA ORDER'}</span><h1>${ok?'Your order is confirmed.':o.status==='processing'?'Your order is placed.':'Almost there.'}</h1><p>${ok||o.status==='processing'?'Keep your order number: you’ll need it, with your email, to track your order. Stripe will also email you a receipt.':'We’re still waiting for confirmation from Stripe. Refresh this page in a minute, or track your order with the number below.'}</p>${orderCard(o)}<div class="hero-actions"><a class="btn" href="#/track-order?order=${encodeURIComponent(o.order_number)}">Track this order</a><a class="text-link" href="#/shop">Continue shopping ↗</a></div>`}
 catch(e){box.innerHTML=`<span class="eyebrow">YOUR DOCNOVA ORDER</span><h1>We couldn’t load this order.</h1><p>${esc(e.message||'Please try again in a moment.')} If you were charged, your order is safe: track it with the order number from your receipt.</p><a class="btn" href="#/track-order">Track your order</a>`}}
function trackOrderPage(){return `<div class="content order-page"><span class="eyebrow">HERE TO HELP</span><h1>Track your order.</h1><p>Enter your order number (it starts with DN-) and the email address you used at checkout.</p>
 <form class="track-form" onsubmit="event.preventDefault();trackOrder()"><label>Order number<input id="track-number" name="order" required placeholder="DN-260926-7K4QP" autocomplete="off" value="${esc(hashParam('order'))}" pattern="\\s*[Dd][Nn]-\\d{6}-[A-Za-z0-9]{5}\\s*" title="For example DN-260926-7K4QP"></label><label>Email address<input id="track-email" type="email" required autocomplete="email" value="${esc(hashParam('email'))}"></label><button class="btn" id="track-button">Find my order</button></form><div id="track-result" role="status"></div></div>`}
async function trackOrder(){const out=$('#track-result'),btn=$('#track-button');btn.disabled=true;out.innerHTML='<p class="fine">Looking up your order…</p>';
 try{const res=await fetch('/api/track',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_number:$('#track-number').value.trim(),email:$('#track-email').value.trim()})});const o=await res.json().catch(()=>({}));
  out.innerHTML=res.ok?orderCard(o):`<div class="notice">${esc(o.message||'We couldn’t look up that order right now.')}</div>`}
 catch(e){out.innerHTML='<div class="notice">Order tracking is unavailable right now. Please try again shortly.</div>'}btn.disabled=false}

// ---- Live Google reviews (served by /api/reviews from Google's Places API; refreshed hourly on the server)
var reviewsRequest=null;
function starsMarkup(r,label){const pct=Math.max(0,Math.min(100,(Number(r)||0)/5*100));return `<span class="stars" style="--pct:${pct}%" role="img" aria-label="${label||('Rated '+(Number(r)||0).toFixed(1)+' out of 5')}"></span>`}
function reviewCard(r,i){const initial=esc((r.author||'G').trim().charAt(0).toUpperCase());const long=(r.text||'').length>260;
 return `<article class="gr-card"><div class="gr-head"><span class="gr-avatar">${r.photo?`<img src="${esc(r.photo)}" alt="" referrerpolicy="no-referrer" loading="lazy" onerror="this.remove()">`:''}<b>${initial}</b></span><div><h3>${r.author_url?`<a href="${esc(r.author_url)}" target="_blank" rel="noopener">${esc(r.author)}</a>`:esc(r.author)}</h3><small>${esc(r.when||'')}</small></div></div>${starsMarkup(r.rating)}
 ${r.text?`<p class="gr-text${long?' clamp':''}" id="gr-text-${i}">${esc(r.text)}</p>${long?`<button class="gr-more" aria-expanded="false" aria-controls="gr-text-${i}" onclick="const t=document.getElementById('gr-text-${i}');const o=t.classList.toggle('clamp');this.setAttribute('aria-expanded',!o);this.textContent=o?'Read more':'Show less'">Read more</button>`:''}`:'<p class="gr-text fine">Rated without a written review.</p>'}
 <div class="gr-foot"><span class="gr-g" aria-hidden="true">G</span><span>Posted on Google Maps</span>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">View ↗</a>`:''}</div></article>`}
function reviewsSummary(rating,count,links,mapsUrl,note){const n=count||0;
 return `<span class="eyebrow">GOOGLE REVIEWS</span><h2>Worn on shift.<br><em>Rated on Google.</em></h2><div class="gr-score"><span class="gr-num">${(Number(rating)||0).toFixed(1)}</span><div>${starsMarkup(rating,'Average rating '+(Number(rating)||0).toFixed(1)+' out of 5')}<small>Based on ${n} Google review${n===1?'':'s'}</small></div></div><div class="gr-actions"><a class="btn outline" href="${esc(mapsUrl||links.maps)}" target="_blank" rel="noopener">Read all reviews on Google ↗</a><a class="text-link" href="${esc(links.write)}" target="_blank" rel="noopener">Write a review</a></div><p class="fine gr-note">${note}</p>`}
function reviewsMarkup(d){const links=d.links||{};
 if(d.live&&d.reviews&&d.reviews.length){
  // Highest-rated first, then newest; four fit the layout. The note below says so, as Google's policy asks.
  const top=[...d.reviews].sort((a,b)=>(b.rating||0)-(a.rating||0)||String(b.published||'').localeCompare(String(a.published||''))).slice(0,4);
  return {summary:reviewsSummary(d.rating,d.count,links,d.maps_url,'Live from Google Maps, updated hourly. Showing our highest-rated recent reviews, unedited. The rating above includes every review.'),
   list:top.map((r,i)=>reviewCard({...r,url:r.url||d.maps_url||links.maps},i)).join(''),n:top.length}}
 const f=d.featured;
 if(f&&f.reviews&&f.reviews.length){
  return {summary:reviewsSummary(f.rating,f.count,links,null,'Selected reviews from our Google profile, shown word for word. The rating above includes every review.'),
   list:f.reviews.slice(0,4).map((r,i)=>reviewCard({...r,url:links.maps},i)).join(''),n:Math.min(4,f.reviews.length)}}
 return {summary:`<span class="eyebrow">GOOGLE REVIEWS</span><h2>Worn on shift.<br><em>Rated on Google.</em></h2><p>Read what healthcare professionals say about DocNova scrubs and medical essentials on Google.</p><div class="gr-actions"><a class="btn" href="${esc(links.maps)}" target="_blank" rel="noopener">Read our Google reviews ↗</a><a class="text-link" href="${esc(links.write)}" target="_blank" rel="noopener">Write a review</a></div>`,list:'',n:0}}
function loadGoogleReviews(){const boxes=document.querySelectorAll('.g-reviews');if(!boxes.length)return;
 reviewsRequest=reviewsRequest||fetch('/api/reviews').then(r=>r.ok?r.json():Promise.reject()).catch(()=>({live:false,links:{maps:'https://www.google.com/maps/place/?q=place_id:ChIJsYc-YLZng2URQNsyBvUhTec',write:'https://search.google.com/local/writereview?placeid=ChIJsYc-YLZng2URQNsyBvUhTec'}}));
 reviewsRequest.then(d=>{const m=reviewsMarkup(d);boxes.forEach(b=>{b.querySelector('.gr-summary').innerHTML=m.summary;const l=b.querySelector('.gr-list');l.innerHTML=m.list;l.hidden=!m.list;l.dataset.count=m.n;b.classList.toggle('gr-live',!!m.list)})})}
